/** Inline-SVG eines Icons. fill z. B. "url(#dcGold)" für geprägtes Gold. */
export function icon(name, { cls = "", fill = "currentColor" } = {}) {
  const body = ICONS[name];
  if (!body) return "";
  return `<svg class="dc-ico ${cls}" viewBox="0 0 ${ICON_SIZE} ${ICON_SIZE}" aria-hidden="true"><g fill="${fill}">${body}</g></svg>`;
}

/** Nur der Pfad, zum Einbetten in ein vorhandenes SVG. */
export function iconPath(name, { x = 0, y = 0, size = 24, fill = "currentColor", cls = "" } = {}) {
  const body = ICONS[name];
  if (!body) return "";
  const s = size / ICON_SIZE;
  return `<g class="${cls}" transform="translate(${x - size / 2} ${y - size / 2}) scale(${s})" fill="${fill}">${body}</g>`;
}
